import { useEffect, useState } from "react";
import { toast } from "react-hot-toast";
import "../App.css";

function Profile() {
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const token = localStorage.getItem("gigora_access_token");

    if (!token) {
      setLoading(false);
      return;
    }

    const fetchProfile = async () => {
      try {
        const response = await fetch("http://127.0.0.1:8000/api/auth/me", {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });

        const data = await response.json();
        const result = data.user || data.data;

        if (!response.ok) {
          throw new Error(data.detail || "Unable to load profile.");
        }

        setProfile(result);
      } catch (err) {
        toast.error(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchProfile();
  }, []);

  const formatDate = (value) => {
    if (!value) return "-";
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) return "-";
    return date.toLocaleDateString(undefined, {
      year: "numeric",
      month: "long",
      day: "numeric",
    });
  };

  return (
    <div className="profile-page">
      <div className="profile-card">
        <h1>User Profile</h1>

        {loading ? (
          <div className="skeleton-grid">
            <div className="skeleton-card" />
            <div className="skeleton-card" />
            <div className="skeleton-card" />
          </div>
        ) : profile ? (
          <div className="profile-grid">
            <div className="profile-detail">
              <h3>Name</h3>
              <p>{profile.name}</p>
            </div>

            <div className="profile-detail">
              <h3>Email</h3>
              <p>{profile.email}</p>
            </div>

            <div className="profile-detail">
              <h3>Current Plan</h3>
              <p className="plan-badge">{profile.plan?.toUpperCase()}</p>
            </div>

            <div className="profile-detail">
              <h3>Join Date</h3>
              <p>{formatDate(profile.created_at || profile.join_date)}</p>
            </div>

            <div className="profile-detail">
              <h3>Requests Used</h3>
              <p>{profile.requests_used ?? 0}</p>
            </div>

            <div className="profile-detail">
              <h3>Remaining Requests</h3>
              <p>{profile.remaining_requests ?? 0}</p>
            </div>
          </div>
        ) : (
          <div className="empty-state-card">
            <h3>Unable to load profile</h3>
            <p>Check your session or try logging in again.</p>
          </div>
        )}
      </div>
    </div>
  );
}

export default Profile;
